{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Direct absolute oral bioavailability in ordinary human conditions is below 20% for tetrabenazine (F=0.013), meptazinol (5.61%), and estradiol (~5%), supporting low bioavailability."
    },
    {
      "card_ids": ["C08"],
      "claim": "Additional high-transfer molecules are reported as low or very low after oral dosing, including aniracetam (extremely low), curcumin (barely 1%), 2ME2 (1-2%), apocynin (<10%), and ferulic acid (3-10%)."
    },
    {
      "card_ids": ["C19"],
      "claim": "The only above-threshold values are single-subject or altered-condition measurements, such as pentazocine 31.6% in one healthy subject, and do not establish high bioavailability."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C19"],
  "decision_summary": "Across ten transferred molecules, direct absolute oral bioavailability values in ordinary human conditions are consistently below 20%; the few higher values are single-subject extremes or altered disease-state measurements, so low is predicted.",
  "evidence_gaps": [
    "One curcumin record reports ~60% oral bioavailability, conflicting with many low curcumin values; its bioavailability type is unspecified.",
    "Some above-threshold values come from cirrhosis or single-subject data and are not ordinary-condition absolute measurements."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C06", "C08"],
  "revision_action": "initial",
  "supportive_card_ids": ["C06", "C08"]
}

